/** The feed quotes Value RUB for Nominal units of the currency. */
export function parseCnyRubRate(xml) {
    for (const [, row] of xml.matchAll(/<Valute\b[^>]*>([\s\S]*?)<\/Valute>/g)) {
        if (!/<CharCode>\s*CNY\s*<\/CharCode>/.test(row))
            continue;
        const nominal = Number(/<Nominal>\s*(\d+)\s*<\/Nominal>/.exec(row)?.[1]);
        const value = Number(/<Value>\s*(\d+(?:[,.]\d+)?)\s*<\/Value>/.exec(row)?.[1]?.replace(',', '.'));
        if (nominal > 0 && Number.isFinite(value) && value > 0)
            return value / nominal;
    }
    return undefined;
}

export function loadCnyRubRate() {
    if (process.env.DEVNEYA_MANAGED_BUILD !== '1')
        return Promise.resolve(undefined);
